def attach_particle(word: str, particle: str) -> str:
    # Sino-Korean digits and their pronunciations
    sino_korean = {
        '0': '영',
        '1': '일',
        '2': '이',
        '3': '삼',
        '4': '사',
        '5': '오',
        '6': '육',
        '7': '칠',
        '8': '팔',
        '9': '구'
    }

    def has_batchim(text):
        """Check if text ends with a batchim (final consonant)"""
        if not text:
            return False

        last_char = text[-1]

        # If it's a digit, convert to Sino-Korean and check recursively
        if last_char.isdigit():
            return has_batchim(sino_korean[last_char])

        # Check if it's a Hangul syllable
        code = ord(last_char)
        if 0xAC00 <= code <= 0xD7A3:  # Hangul syllables range
            # Formula: (code - 0xAC00) % 28 gives the batchim index
            # batchim index 0 means no batchim (vowel ending)
            batchim_index = (code - 0xAC00) % 28
            return batchim_index != 0

        return False

    def get_last_consonant_type(text):
        """Get the type of final consonant for special cases"""
        if not text:
            return None

        last_char = text[-1]

        if last_char.isdigit():
            return get_last_consonant_type(sino_korean[last_char])

        code = ord(last_char)
        if 0xAC00 <= code <= 0xD7A3:
            batchim_index = (code - 0xAC00) % 28
            if batchim_index == 0:
                return 'vowel'
            # ㄹ batchim is at index 8
            if batchim_index == 8:
                return 'rieul'
            return 'consonant'

        return None

    # Determine which form of particle to use
    has_final_consonant = has_batchim(word)

    # Special handling for "으로/로"
    if particle == "으로/로":
        consonant_type = get_last_consonant_type(word)
        if consonant_type == 'rieul' or not has_final_consonant:
            return word + "로"
        else:
            return word + "으로"

    # For other particles
    forms = particle.split('/')
    if has_final_consonant:
        return word + forms[0]
    else:
        return word + forms[1]

