from solution import attach_particle

def test_basic():
    assert attach_particle('책', '을/를') == '책을'
    assert attach_particle('3', '이/가') == '3이'

def test_jo_vowel():
    assert attach_particle('1000000000000', '이/가') == '1000000000000가'

def test_jo_eul():
    assert attach_particle('1000000000000', '을/를') == '1000000000000를'

def test_jo_euro():
    assert attach_particle('1000000000000', '으로/로') == '1000000000000로'

def test_jo_with_trailing():
    assert attach_particle('5000000000000', '은/는') == '5000000000000는'

def test_rieul_digit():
    assert attach_particle('1', '으로/로') == '1로'
    assert attach_particle('11', '으로/로') == '11로'

def test_rieul_hangul():
    assert attach_particle('서울', '으로/로') == '서울로'

def test_euro_batchim():
    assert attach_particle('집', '으로/로') == '집으로'
    assert attach_particle('6', '으로/로') == '6으로'

def test_zero():
    assert attach_particle('0', '은/는') == '0은'

def test_tens():
    assert attach_particle('10', '과/와') == '10과'
    assert attach_particle('10', '으로/로') == '10으로'

def test_vowel_hangul():
    assert attach_particle('나', '과/와') == '나와'

def test_digit_vowel():
    assert attach_particle('2', '과/와') == '2와'
    assert attach_particle('4', '이/가') == '4가'

